package main

import (
	"net/http"
	"strconv"
	"strings"

	"github.com/gin-gonic/gin"
)

type RequestBody struct {
	Expression string `json:"expression" binding:"required"`
}

type ResponseBody struct {
	Result string `json:"result"`
}

func calculate(expression string) (string, error) {
	// Replace spaces and split the expression
	tokens := strings.Fields(expression)
	if len(tokens) == 0 {
		return "", nil
	}

	// Simple evaluation of the expression
	result, err := eval(tokens)
	if err != nil {
		return "", err
	}

	return strconv.FormatFloat(result, 'f', -1, 64), nil
}

func eval(tokens []string) (float64, error) {
	// This is a very basic evaluator for demonstration purposes
	// It only handles + and * operations and assumes valid input
	var result float64
	var currentOp string

	for _, token := range tokens {
		switch token {
		case "+":
			currentOp = "+"
		case "*":
			currentOp = "*"
		default:
			num, err := strconv.ParseFloat(token, 64)
			if err != nil {
				return 0, err
			}
			if currentOp == "+" {
				result += num
			} else if currentOp == "*" {
				result *= num
			} else {
				result = num
			}
		}
	}

	return result, nil
}

func main() {
	r := gin.Default()

	r.POST("/calculator", func(c *gin.Context) {
		var requestBody RequestBody
		if err := c.ShouldBindJSON(&requestBody); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid input"})
			return
		}

		result, err := calculate(requestBody.Expression)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid input"})
			return
		}

		c.JSON(http.StatusOK, ResponseBody{Result: result})
	})

	r.Run("0.0.0.0:5000")
}
